import { InfoIcon, ToggleSwitch } from '@wix/design-system';
import type { FC } from 'react';
import React, { useContext } from 'react';

import { RicosContext, ZIndexContext } from './../../ricos-context/index.js';
import { ListItemSelect } from './../list-item-select/list-item-select.js';

import styles from './list-item-toggle-scss.js';

type Props = {
  dataHook: string;
  title: string;
  infoContent?: string;
  selected: boolean;
  disabled?: boolean;
  onChange: () => void;
};

/**
 * A dropdown row whose option is a switch rather than a selection: the same primitive as its
 * neighbours — `_shared/list-item-select` — with the switch in the `suffix` slot, so fill, title
 * colour and insets come from WDS' row tokens rather than being restated here.
 *
 * `selected` does not reach the WDS row, where it would paint the blue fill of a chosen option.
 * The switch shows the state; `aria-selected` carries it.
 *
 * The info icon sits in the title, riding high against the label as WDS `FieldSet` had it — which
 * costs the title's truncation, see the `.row` rule in the stylesheet.
 */
export const ListItemToggle: FC<Props> = ({
  title,
  infoContent,
  dataHook,
  selected,
  onChange,
  disabled,
}) => {
  const { portal } = useContext(RicosContext);
  const zIndexService = useContext(ZIndexContext);

  return (
    <ListItemSelect
      className={styles.row}
      title={
        <>
          {title}
          {infoContent && (
            <span
              className={styles.info}
              // The icon alone is exempt from the row's click — the label around it must keep
              // toggling, so the guard cannot go on the title as a whole.
              onClick={event => event.stopPropagation()}
            >
              <InfoIcon
                size="small"
                content={infoContent}
                tooltipProps={{
                  // The element, not a predicate: WDS walks ancestors with `getParentNode`, which
                  // returns <html> for <html>, so a never-matching predicate recurses forever.
                  appendTo: portal ?? undefined,
                  // The portal sits at body level, so WDS would position in document coordinates
                  // while the dropdown is placed in viewport ones.
                  fixed: true,
                  zIndex: zIndexService.getZIndex('TOOLTIP'),
                  size: 'small',
                  enterDelay: 300,
                }}
              />
            </span>
          )}
        </>
      }
      selected={false}
      aria-selected={selected}
      disabled={disabled}
      onSelect={onChange}
      suffix={
        <span
          className={styles.suffix}
          // The switch acts on its own click, and a click leaves it focused, so it acts on Enter
          // (WDS' handler) and Space (native) too. Each would reach the row and toggle a second
          // time. Only those three events are contained — Escape still reaches the panel.
          onClick={event => event.stopPropagation()}
          onKeyDown={event => {
            if (event.key === 'Enter' || event.key === ' ') {
              event.stopPropagation();
            }
          }}
        >
          <ToggleSwitch
            dataHook={dataHook}
            size="small"
            checked={selected}
            disabled={disabled}
            onChange={onChange}
            // Its neighbours are one tab stop each: the row is the stop, not the switch.
            tabIndex={-1}
          />
        </span>
      }
    />
  );
};
