import { TIPTAP_ACTION_BUTTON_TYPE, TIPTAP_LINK_BUTTON_TYPE } from './../../ricos-content/index.js';
import type { CommandProps } from './../../tiptap/core/index.js';
import { Plugin, PluginKey } from './../../tiptap/pm/state.js';
import { Decoration, DecorationSet } from './../../tiptap/pm/view.js';
import { createRicosNodeExtension } from './../../plugin-commons/index.js';

import { ACTION_BUTTON_TYPE, LINK_BUTTON_TYPE } from '../types.js';
import { Button as Component } from './component.js';

declare module './../../tiptap/core' {
  interface Commands<ReturnType> {
    button: {
      /**
       * Sets value of temporary hover preview in Button settings.
       */
      setHoverPreview: (applyPreview: boolean) => ReturnType;
    };
  }
}

const getButtonExtension = (name: string, disableResize: boolean) => [
  createRicosNodeExtension({
    groups: ['custom-styles', 'not-overtypable'],
    type: 'react-node',
    reconfigure: (config, _extensions, props, settings) => {
      return {
        ...config,
        disableResize,
        isTextWrap: props.isTextWrap ?? true,
        addOptions: () => settings,
      };
    },
    Component,
    name,
    createExtensionConfig() {
      const HOVER_PREVIEW_PLUGIN_KEY = new PluginKey(this.name + 'hoverPreview');

      return {
        name: this.name,
        group:
          'block smartBlockCellContent layoutCellContent collapsibleListItemBodyContent tableCellContent',
        selectable: true,
        draggable: true,
        addAttributes: () => ({
          type: null,
          containerData: null,
          styles: null,
          text: null,
          link: null,
        }),
        addCommands() {
          return {
            setHoverPreview:
              applyPreview =>
              ({ tr, dispatch }: CommandProps) => {
                dispatch?.(tr.setMeta(HOVER_PREVIEW_PLUGIN_KEY, applyPreview));

                return true;
              },
          };
        },
        addProseMirrorPlugins() {
          return [
            new Plugin({
              key: HOVER_PREVIEW_PLUGIN_KEY,

              state: {
                init() {
                  return { applyPreview: false };
                },
                apply(tr, value) {
                  const applyPreview = tr.getMeta(HOVER_PREVIEW_PLUGIN_KEY);

                  if (applyPreview === undefined) {
                    return value;
                  }

                  return { applyPreview };
                },
              },

              props: {
                decorations(state) {
                  const { applyPreview } = HOVER_PREVIEW_PLUGIN_KEY.getState(state);
                  const { from, to } = state.selection;

                  if (!applyPreview) {
                    return null;
                  }

                  return DecorationSet.create(state.doc, [
                    Decoration.node(from, to, {
                      class: 'forced-hover',
                    }),
                  ]);
                },
              },
            }),
          ];
        },
      };
    },
  }),
];

export const tiptapExtensionsMap = ({ disableResize }: { disableResize: boolean }) => ({
  [LINK_BUTTON_TYPE]: getButtonExtension(TIPTAP_LINK_BUTTON_TYPE, disableResize),
  [ACTION_BUTTON_TYPE]: getButtonExtension(TIPTAP_ACTION_BUTTON_TYPE, disableResize),
});
