// Leading+trailing throttle (same as the lodash.throttle defaults we used):
// invokes immediately when idle, and schedules one trailing call with the
// latest arguments for invocations that arrive inside the wait window.
export function throttle<Args extends unknown[]>(
  fn: (...args: Args) => void,
  wait: number
): ((...args: Args) => void) & { cancel: () => void } {
  let timer: ReturnType<typeof setTimeout> | undefined;
  let lastArgs: Args | undefined;
  let lastInvoke = 0;
  const invoke = () => {
    timer = undefined;
    // No-op if there's nothing pending — guards against a stale trailing timer
    // firing after an immediate invoke already consumed the args.
    if (lastArgs === undefined) {
      return;
    }
    lastInvoke = Date.now();
    const args = lastArgs;
    lastArgs = undefined;
    fn(...args);
  };
  const throttled = (...args: Args) => {
    lastArgs = args;
    const remaining = wait - (Date.now() - lastInvoke);
    if (remaining <= 0) {
      // Cancel any pending trailing timer so it can't fire again later.
      clearTimeout(timer);
      invoke();
    } else if (!timer) {
      timer = setTimeout(invoke, remaining);
    }
  };
  throttled.cancel = () => {
    clearTimeout(timer);
    timer = undefined;
    lastArgs = undefined;
  };
  return throttled;
}
