import type { FC } from 'react';
import React, { useContext, useState } from 'react';

import { ModalServiceContext } from './../../ricos-context/index.js';
import { useBiNext } from './../../_shared/bi-context-provider/bi-context-provider.js';
import type { PmActionButtonNode, PmLinkButtonNode, PmNodeType } from './../../_shared/pm-node-types.js';
import { useNodeAttrs } from './../../_shared/use-node-attrs.js';
import {
  useClickOutside,
  usePanelContainerElement,
} from './../../ui-components/index.js';

import type { SettingsTab } from '../constants.js';
import { SETTINGS_TAB, buttonsModals } from '../constants.js';
import type { ACTION_BUTTON_TYPE, ButtonPluginEditorConfigCommon } from '../types.js';
import { LINK_BUTTON_TYPE } from '../types.js';
import { SettingsModalContent } from './settings-modal-content.js';

interface Props {
  nodeId: string;
  modalId: string;
  settings: ButtonPluginEditorConfigCommon;
  type: typeof LINK_BUTTON_TYPE | typeof ACTION_BUTTON_TYPE;
  activeTab?: SettingsTab;
  referenceElement?: HTMLElement;
}

export const ButtonSettingsModal: FC<Props> = ({
  nodeId,
  settings,
  type,
  modalId,
  activeTab: tab,
  referenceElement,
}) => {
  const modalService = useContext(ModalServiceContext) || {};

  const containerEl = usePanelContainerElement();

  const nodeType: typeof PmNodeType.LINK_BUTTON | typeof PmNodeType.ACTION_BUTTON =
    type === LINK_BUTTON_TYPE ? 'LINK_BUTTON' : 'ACTION_BUTTON';

  const logBi = useBiNext({
    modalId: buttonsModals.settings[type],
    pluginId: nodeType === 'LINK_BUTTON' ? 'linkButton' : 'actionButton',
    nodeId,
  });

  const { patchPmNodeAttrs, pmNodeAttrs } = useNodeAttrs(nodeId, nodeType);

  const [activeTab, setActiveTab] = useState<SettingsTab>(tab ?? SETTINGS_TAB.SETTINGS);

  const handleOnChange = (data: Partial<(PmLinkButtonNode | PmActionButtonNode)['attrs']>) =>
    patchPmNodeAttrs?.(data);

  const isColorPickerModalOpen = () => modalService.isModalOpen(buttonsModals.colorPicker);

  const closeModal = () => modalService.closeModal(modalId);

  useClickOutside({
    containerRef: { current: containerEl },
    onClickOutside: (e: MouseEvent | TouchEvent) => {
      const target = e.target as HTMLElement | null;

      if (referenceElement?.contains(target as Node)) {
        return;
      }

      closeModal();
    },
    disable: isColorPickerModalOpen(),
  });

  return pmNodeAttrs ? (
    <SettingsModalContent
      buttonData={pmNodeAttrs}
      config={settings}
      onClose={closeModal}
      onChange={handleOnChange}
      nodeId={nodeId}
      nodeType={nodeType}
      activeTab={activeTab}
      onTabChange={setActiveTab}
      logBi={logBi}
    />
  ) : null;
};
