import { ButtonPill, ButtonPillSmall } from '@wix/wix-ui-icons-common/lazy';

import buttonDataDefaults from './../ricos-schema/legacy/statics/button.defaults.json.js';
import { ButtonData_Type } from './../ricos-schema/next-schema/index.js';
import type { EditorPluginCreator } from './../ricos-types/index.js';
import {
  Node_Type,
  RicosPluginToolbarNames,
  quickActionsModalSections,
} from './../ricos-types/index.js';
import { getInitialLinkData } from './../_shared/link/get-initial-link-data.js';

import { actionButtonConverter, linkButtonConverter } from './button-converters.js';
import { DEFAULT_CONFIG } from './constants.js';
import { getAddButtons } from './get-add-buttons.js';
import { getToolbarButtons } from './get-toolbar-buttons.js';
import { tiptapExtensionsMap } from './tiptap/tiptap.js';
import type { ActionButtonPluginEditorConfig, LinkButtonPluginEditorConfig } from './types.js';
import { ACTION_BUTTON_TYPE, LINK_BUTTON_TYPE } from './types.js';

export const pluginLinkButton: EditorPluginCreator<LinkButtonPluginEditorConfig> = config => {
  const type = LINK_BUTTON_TYPE;
  return {
    config: { type: 'linkButton' as const, ...DEFAULT_CONFIG, ...config },
    type,
    pmMarkConverters: [],
    pmNodeConverters: [linkButtonConverter],
    toolbar: {
      names: [RicosPluginToolbarNames.LINK_BUTTON],
      getButtons: (c, services) => getToolbarButtons({ config: c, services, type }),
    },
    getAddButtons: (c, services) => getAddButtons(c, services, type),
    tiptapExtensions: tiptapExtensionsMap({ disableResize: config?.disableResize ?? false })[type],
    getQuickActions: ({ pluginServices }) => [
      {
        id: Node_Type.BUTTON,
        icon: pluginServices?.context.isMobile ? ButtonPill : ButtonPillSmall,
        title: 'QuickActionsPlugin_ActionTitle_Button',
        section: quickActionsModalSections.FormatLayout,
        tags: ['action', 'link', 'call-to-action', 'interactive', 'clickable'],
        command: ({ publicCommands }) => {
          const initialLinkOptions = getInitialLinkData(
            pluginServices.editorProps.generalLinkSettings?.initialLinkOptions
          );
          publicCommands.insertBlockWithBlankLines(LINK_BUTTON_TYPE, {
            ...buttonDataDefaults,
            link: initialLinkOptions,
            // @ts-expect-error
            type: ButtonData_Type.LINK,
          });
        },
      },
    ],
  };
};

export const pluginActionButton: EditorPluginCreator<ActionButtonPluginEditorConfig> = config => {
  const type = ACTION_BUTTON_TYPE;
  return {
    config: { type: 'actionButton' as const, ...DEFAULT_CONFIG, ...config },
    type,
    pmMarkConverters: [],
    pmNodeConverters: [actionButtonConverter],
    toolbar: {
      names: [RicosPluginToolbarNames.ACTION_BUTTON],
      getButtons: (config, services) => getToolbarButtons({ config, services, type }),
    },
    getAddButtons: (config, services) => getAddButtons(config, services, type),
    tiptapExtensions: tiptapExtensionsMap({ disableResize: config?.disableResize ?? false })[type],
  };
};
