import type { RicosServices, ToolbarButton } from './../ricos-types/index.js';
import { createAnimationButton } from './../_shared/plugin-toolbar/create-animation-button.js';
import { createDeleteButton } from './../_shared/plugin-toolbar/create-delete-button.js';
import { createLinkButton } from './../_shared/plugin-toolbar/create-link-button.js';
import { createNodeAlignmentButton } from './../_shared/plugin-toolbar/create-node-alignment-button.js';
import { createSettingsButton } from './../_shared/plugin-toolbar/create-settings-button.js';
import { createSeparator } from './../_shared/plugin-toolbar/separator/create-separator.js';

import { buttonsModals } from './constants.js';
import { ButtonSettingsModal } from './modals/settings-modal.js';
import type {
  ACTION_BUTTON_TYPE,
  ActionButtonPluginEditorConfig,
  LINK_BUTTON_TYPE,
  LinkButtonPluginEditorConfig,
} from './types.js';

export const getToolbarButtons = ({
  config,
  services,
  type,
}:
  | {
      type: typeof LINK_BUTTON_TYPE;
      services: RicosServices;
      config: LinkButtonPluginEditorConfig;
    }
  | {
      type: typeof ACTION_BUTTON_TYPE;
      services: RicosServices;
      config: ActionButtonPluginEditorConfig;
    }): ToolbarButton[] => {
  const alignmentModalId = buttonsModals.alignment[type];
  const settingsModalId = buttonsModals.settings[type];

  const alignmentButton = createNodeAlignmentButton({ services, modalId: alignmentModalId });
  const linkButton = createLinkButton(services);
  const settingsButton = createSettingsButton({
    modalId: settingsModalId,
    command: ({ modals, referenceElement, attributes }) => {
      modals.togglePluginPanel({
        id: settingsModalId,
        isMobile: services.context.isMobile,
        Component: ButtonSettingsModal,
        componentProps: {
          nodeId: attributes.selectedNode?.attrs.id,
          settings: config,
          type,
          modalId: settingsModalId,
          referenceElement,
        },
        positioning: {
          referenceElement:
            referenceElement?.closest('[data-hook~=floating-plugin-toolbar]') ?? referenceElement,
          placement: 'right-start',
        },
        onClickOutside: {
          on: 'pointerup',
          handler: () => {},
        },
        focusReturnElement: referenceElement,
      });
    },
  });
  const separator = createSeparator();
  const animation = createAnimationButton(services);
  const deleteButton = createDeleteButton();

  return services.context.environment === 'wixel'
    ? [settingsButton, linkButton, alignmentButton, animation, deleteButton]
    : [alignmentButton, linkButton, settingsButton, animation, separator, deleteButton];
};
