import React, { useContext, useEffect, useMemo, useRef } from 'react';
import { flushSync } from 'react-dom';

import { EditorContext, RicosContext } from './../../ricos-context/index.js';
import { useSelection } from './../../ricos-context/selection-context.js';
import { PluginContainerData_Alignment } from './../../ricos-schema/next-schema/index.js';
import type { PluginProps } from './../../ricos-types/index.js';
import { isOnlyNodeSelected } from './../../_shared/is-only-node-selected.js';
import { throttle } from './../../_shared/throttle.js';

import { type Enable, createResizeHandler } from './create-resize-handler.js';

const getEnableMap = (
  disabled: boolean,
  verticallyResizable: boolean,
  alignment?: PluginContainerData_Alignment | null,
  handleMode: ResizeHandleMode = 'all'
): Enable => {
  if (disabled) {
    return {
      left: false,
      right: false,
      top: false,
      bottom: false,
      topRight: false,
      bottomRight: false,
      topLeft: false,
      bottomLeft: false,
    };
  }

  if (handleMode === 'corners') {
    const cornersEnabledByAlignment =
      alignment === PluginContainerData_Alignment.LEFT
        ? { topRight: true, bottomRight: true, topLeft: false, bottomLeft: false }
        : alignment === PluginContainerData_Alignment.RIGHT
          ? { topRight: false, bottomRight: false, topLeft: true, bottomLeft: true }
          : { topRight: true, bottomRight: true, topLeft: true, bottomLeft: true };

    return {
      left: false,
      right: false,
      top: false,
      bottom: false,
      ...cornersEnabledByAlignment,
    };
  }

  switch (alignment) {
    case PluginContainerData_Alignment.LEFT:
      return {
        left: false,
        right: true,
        top: verticallyResizable,
        bottom: verticallyResizable,
        topRight: verticallyResizable,
        bottomRight: verticallyResizable,
        topLeft: false,
        bottomLeft: false,
      };
    case PluginContainerData_Alignment.RIGHT:
      return {
        left: true,
        right: false,
        top: verticallyResizable,
        bottom: verticallyResizable,
        topRight: false,
        bottomRight: false,
        topLeft: verticallyResizable,
        bottomLeft: verticallyResizable,
      };
    default:
      return {
        left: true,
        right: true,
        top: verticallyResizable,
        bottom: verticallyResizable,
        topRight: verticallyResizable,
        bottomRight: verticallyResizable,
        topLeft: verticallyResizable,
        bottomLeft: verticallyResizable,
      };
  }
};

const useMaxContentWidth = (props: PluginProps, minWidth: number) => {
  const { editor, decorations } = props;

  // Decorations list is always new, regardless of the changes in the decorations
  // We need to use a key to force a re-render of the max content width
  const decorationKey = React.useMemo(() => {
    return decorations
      .map((decoration: $TSFixMe) => decoration.type?.attrs['data-breakout'] ?? 'unknown')
      .join(',');
  }, [decorations]);

  return React.useCallback(() => {
    const isBreakoutFullWidth = decorations.some(
      (decoration: $TSFixMe) => decoration.type?.attrs['data-breakout'] === 'fullWidth'
    );

    if (isBreakoutFullWidth) {
      return editor.view.dom.clientWidth;
    }

    const nodeContainer = (editor.view.dom.querySelector('[data-breakout="normal"]') ??
      editor.view.dom.firstChild) as HTMLElement;
    const nodeContentStyles = window.getComputedStyle(nodeContainer);
    const paddingStart = parseInt(nodeContentStyles.paddingInlineStart) || 0;
    const paddingEnd = parseInt(nodeContentStyles.paddingInlineEnd) || 0;

    return Math.max(minWidth, nodeContainer.clientWidth - paddingStart - paddingEnd);
  }, [decorationKey]);
};

export type ResizerOptions = {
  minWidth?: number;
  verticallyResizable?: boolean;
  lockAspectRatio?: boolean;
  saveDimensions?: boolean;
  expandToFullWidthOnOverdrag?: boolean;
  /** Controls which resize handles are exposed when the node is selected. */
  handleMode?: ResizeHandleMode;
  /** @deprecated Use `handleMode: 'corners'` instead. */
  cornersOnly?: boolean;
};

type ResizeHandleMode = 'all' | 'corners';

const defaultOptions = {
  minWidth: 15,
  verticallyResizable: false,
  lockAspectRatio: false,
  saveDimensions: false,
  expandToFullWidthOnOverdrag: false,
  handleMode: 'all',
} satisfies ResizerOptions;

export const createResizerHoc =
  (options: ResizerOptions = defaultOptions) =>
  (Component: React.ComponentType<PluginProps>) => {
    return (props: PluginProps) => {
      const {
        minWidth = defaultOptions.minWidth,
        verticallyResizable = defaultOptions.verticallyResizable,
        lockAspectRatio = defaultOptions.lockAspectRatio,
        saveDimensions = defaultOptions.saveDimensions,
        expandToFullWidthOnOverdrag = defaultOptions.expandToFullWidthOnOverdrag,
        handleMode = options.cornersOnly ? 'corners' : defaultOptions.handleMode,
      } = options;
      const { isMobile } = useContext(RicosContext);
      const { updateAttributes, componentData } = props;
      const {
        adapter: { tiptapEditor: editor },
      } = React.useContext(EditorContext);
      const selection = useSelection();
      const selected = React.useMemo(
        () => (componentData?.id ? isOnlyNodeSelected(editor.state, componentData.id) : false),
        [editor.state, componentData?.id, selection]
      );
      const getMinWidth = React.useCallback(() => minWidth, [minWidth]);
      const getMaxWidthLatest = useMaxContentWidth(props, minWidth);
      // Keep getMaxWidth identity stable across re-renders so the resize handler is not torn
      // down mid-drag when commits to containerData change the breakout decoration set (which
      // would otherwise change useMaxContentWidth's identity).
      const getMaxWidthRef = useRef(getMaxWidthLatest);
      getMaxWidthRef.current = getMaxWidthLatest;
      const getMaxWidth = React.useCallback(() => getMaxWidthRef.current(), []);
      const alignment =
        componentData.containerData?.alignment ?? PluginContainerData_Alignment.CENTER;
      const enableMap = React.useMemo(
        () => getEnableMap(!selected, verticallyResizable, alignment, handleMode),
        [selected, verticallyResizable, alignment, handleMode]
      );
      const contentRef = useRef<HTMLDivElement>(null);

      const onResize = React.useCallback(
        (dimensions: { width: number; height: number; isExceedingMaxWidth?: boolean }) => {
          const { width } = dimensions;
          const widthAttr =
            expandToFullWidthOnOverdrag && dimensions.isExceedingMaxWidth
              ? ({ size: 'FULL_WIDTH' } as const)
              : { custom: width };

          flushSync(() => {
            updateAttributes({
              containerData: {
                ...props.componentData.containerData,
                width: widthAttr,
              },
            });
          });
        },
        // eslint-disable-next-line react-hooks/exhaustive-deps
        [updateAttributes, alignment, expandToFullWidthOnOverdrag]
      );

      // FIXME: throttling is needed to prevent the editor from freezing up while some element is
      // being resized. However, the throttled size is applied to the Component and its container
      // while the Resizer itself is "sandwiched" between the two and will always be the immediate
      // (not throttled) size as it handles its own size changes internally. This results in a
      // visual glitch as the Resizer's size is not in sync with the debounced Component's size
      // while resizing.
      const onResizeThrottle = useMemo(() => throttle(onResize, 16), [onResize]);

      const onResizeStop = React.useCallback(
        (dimensions: { width: number; height: number; isExceedingMaxWidth?: boolean }) => {
          onResize(dimensions);

          if (saveDimensions && !dimensions.isExceedingMaxWidth) {
            flushSync(() => {
              updateAttributes({
                dimensions: {
                  width: dimensions.width,
                  height: dimensions.height,
                },
              });
            });
          }
        },
        [onResize, saveDimensions, updateAttributes]
      );

      useEffect(() => {
        if (!contentRef.current) {
          return;
        }

        const cleanup = createResizeHandler({
          resizeElement: contentRef.current,
          isEnabled: selected && !isMobile,
          getMinWidth,
          getMaxWidth,
          enable: enableMap,
          lockAspectRatio,
          alignment,
          onResize: onResizeThrottle,
          onResizeStop,
        });

        return cleanup;
      }, [
        selected,
        getMinWidth,
        getMaxWidth,
        enableMap,
        lockAspectRatio,
        alignment,
        onResizeThrottle,
        onResizeStop,
      ]);

      return (
        <div ref={contentRef} data-resize-container="">
          <Component {...props} />
        </div>
      );
    };
  };

export const ResizerHOC = createResizerHoc();
