import { definePmNodeConverter } from './../pm-converters/types.js';
import type { PmNodeJson } from './../pm-converters/types.js';
import { TIPTAP_ACTION_BUTTON_TYPE, TIPTAP_LINK_BUTTON_TYPE } from './../ricos-content/index.js';
import type { Link as LinkOld } from './../ricos-schema/legacy/wix/rich_content/v1/index.js';
import type { ButtonData, ButtonNode, Link } from './../ricos-schema/next-schema/index.js';
import { Node_Type, PluginContainerData_Alignment } from './../ricos-schema/next-schema/index.js';
import { fromTiptapLinkConverter } from './../_shared/link/link-converters.js';

const toTiptapButtonConvert = (node: ButtonNode): PmNodeJson => {
  const styles = node.buttonData.styles;
  const bgColor = styles?.backgroundColor ?? styles?.colors?.background;
  const bgColorHover = styles?.backgroundColorHover;
  return {
    type: node.buttonData.type === 'LINK' ? TIPTAP_LINK_BUTTON_TYPE : TIPTAP_ACTION_BUTTON_TYPE,
    attrs: {
      ...node.buttonData,
      styles: {
        ...styles,
        // Clear deprecated fields
        border: undefined,
        colors: undefined,
        backgroundColor: undefined,
        backgroundColorHover: undefined,
        // Migrate deprecated backgroundColor to new background union
        background: styles?.background ?? (bgColor ? { type: 'COLOR', color: bgColor } : undefined),
        backgroundHover:
          styles?.backgroundHover ??
          (bgColorHover ? { type: 'COLOR', color: bgColorHover } : undefined),
        textColor: styles?.textColor ?? styles?.colors?.text,
        borderColor: styles?.borderColor ?? styles?.colors?.border,
        borderWidth: styles?.borderWidth ?? styles?.border?.width,
        borderRadius: styles?.borderRadius ?? styles?.border?.radius,
      },
      id: node.id,
    },
  };
};

const fromTiptapButtonConvert = (node: PmNodeJson): ButtonNode => {
  const { id, animation, ...data } = node.attrs || {};
  const linkData = (data as ButtonData).link;
  const containerData = (data as ButtonData).containerData;
  return {
    type: Node_Type.BUTTON,
    id,
    nodes: [],
    buttonData: {
      ...(data as ButtonData),
      ...(animation ? { animation } : {}),
      link: fromTiptapLinkConverter(linkData as LinkOld) as Link,
      containerData: {
        ...containerData,
        alignment: containerData?.alignment || PluginContainerData_Alignment.CENTER,
        width: containerData?.width
          ? {
              ...containerData?.width,
              size: containerData?.width?.custom ? undefined : containerData?.width?.size,
            }
          : undefined,
      },
      text: data.text || '',
    },
  };
};

export const linkButtonConverter = definePmNodeConverter({
  toPm: {
    types: [Node_Type.BUTTON],
    convert: toTiptapButtonConvert,
  },
  fromPm: {
    types: [TIPTAP_LINK_BUTTON_TYPE],
    convert: fromTiptapButtonConvert,
  },
});

export const actionButtonConverter = definePmNodeConverter({
  toPm: {
    types: [Node_Type.BUTTON],
    convert: toTiptapButtonConvert,
  },
  fromPm: {
    types: [TIPTAP_ACTION_BUTTON_TYPE],
    convert: fromTiptapButtonConvert,
  },
});
