export const roundPosition = (value: number): number => Math.round(value * 100) / 100;

export const findLargestGapMidpoint = (stops: { position?: number }[]): number => {
  if (stops.length === 0) {
    return 1;
  }
  const sorted = stops.map(s => s.position ?? 0).sort((a, b) => a - b);
  let bestMid = 1;
  let bestGap = 0;
  for (let i = 0; i < sorted.length - 1; i++) {
    const gap = sorted[i + 1] - sorted[i];
    if (gap > bestGap) {
      bestGap = gap;
      bestMid = sorted[i] + gap / 2;
    }
  }
  const tailGap = 1 - sorted[sorted.length - 1];
  if (tailGap > bestGap) {
    bestMid = sorted[sorted.length - 1] + tailGap / 2;
  }
  return roundPosition(bestMid);
};
