import { Link } from '@wix/wix-ui-icons-common/lazy';
import React from 'react';

import { Link_Target } from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import type { RicosServices, ToolbarButton } from './../../ricos-types/index.js';
import { LinkButton } from './../../toolbars-v3/index.js';

import { PLUGIN_TOOLBAR_LINK_BUTTON } from '../data-hooks.js';
import { toggleLinkModal } from '../link-modal/toggle-link-modal.js';
import type { NamedLink } from '../link/types.js';
import { getNodeInSelection } from '../resolvers/get-node-in-selection.js';
import { getNodeLinkData } from '../resolvers/get-node-link-data.js';
import { isLinkOrAnchorInSelection } from '../resolvers/is-link-or-anchor-in-selection.js';
import { PLUGIN_TOOLBAR_BUTTON_ID } from './plugin-toolbar-buttons-ids.js';

type LinkButtonOptions = {
  /** Adds an alt text input to the link modal, stored as the node's `altText` attribute — for
   *  nodes whose link has no accessible name of its own (e.g. shapes, whose svg is aria-hidden). */
  withAltText?: boolean;
};

export const createLinkButton = (
  services: RicosServices,
  { withAltText }: LinkButtonOptions = {}
): ToolbarButton => {
  return {
    id: PLUGIN_TOOLBAR_BUTTON_ID.LINK,
    type: 'modal',
    attributes: {
      active: isLinkOrAnchorInSelection,
      linkData: getNodeLinkData,
      selectedNode: getNodeInSelection,
    },
    renderer: toolbarItem => <LinkButton toolbarItem={toolbarItem} />,
    dataHook: PLUGIN_TOOLBAR_LINK_BUTTON,
    tooltip: 'ButtonModal_Button_Link',
    icon: Link,
    command: ({ modals, referenceElement, tiptapEditor, attributes }) => {
      const onSave = (link: NamedLink, altText?: string) => {
        const attrs = attributes.selectedNode.attrs;
        tiptapEditor
          .chain()
          .focus()
          .setNodeAttrsById(attrs.id, {
            ...attrs,
            link,
            ...(withAltText ? { altText: altText ?? null } : {}),
          })
          .run();

        services.pluginsEvents.publishPluginLinkable({
          pluginId: attributes.selectedNode.type.name,
          nodeId: attributes.selectedNode.attrs.id,
          link: link.url,
          newTab: link.target === Link_Target.BLANK,
          nofollow: link.rel?.nofollow,
        });
      };

      const onUnlink = () => {
        const { link, ...attrs } = attributes.selectedNode?.attrs ?? {};
        if (withAltText) {
          // The alt text belongs to the link (see LinkButtonOptions), so unlinking removes it too.
          attrs.altText = null;
        }
        tiptapEditor.chain().focus().setNodeAttrsById(attrs.id, attrs).run();
      };

      return toggleLinkModal({
        initialValue: attributes.linkData,
        modalService: modals,
        onSave,
        onUnlink,
        referenceElement,
        showAltText: withAltText,
        initialAltText: withAltText
          ? (attributes.selectedNode?.attrs?.altText ?? undefined)
          : undefined,
      });
    },
  };
};
