import { WixDesignSystemProvider, type PopoverProps } from '@wix/design-system';
import React, { useContext } from 'react';

type UiComponentsContextProps = {
  containerEl: HTMLDivElement;
  children: React.ReactNode;
};

type PopoverAppendTo = PopoverProps['appendTo'];

export const UiComponentsContext = React.createContext(null as unknown as HTMLDivElement);
export const UiComponentsPopoverAppendToContext = React.createContext<PopoverAppendTo | undefined>(
  undefined
);

type UiComponentsPopoverAppendToProviderProps = React.PropsWithChildren<{
  appendTo: PopoverAppendTo;
}>;

export const UiComponentsPopoverAppendToProvider: React.FC<
  UiComponentsPopoverAppendToProviderProps
> = ({ appendTo, children }) => {
  return (
    <UiComponentsPopoverAppendToContext.Provider value={appendTo}>
      {children}
    </UiComponentsPopoverAppendToContext.Provider>
  );
};

export const UiComponentsProvider: React.FC<UiComponentsContextProps> = ({
  children,
  containerEl,
}) => {
  return (
    <WixDesignSystemProvider>
      <UiComponentsContext.Provider value={containerEl}>{children}</UiComponentsContext.Provider>
    </WixDesignSystemProvider>
  );
};

export const usePanelContainerElement = () => useContext(UiComponentsContext);

export const usePopoverAppendToElement = () =>
  useContext(UiComponentsPopoverAppendToContext) ?? usePanelContainerElement();
