import { CloseButton, FillPreview } from '@wix/design-system';
import { DismissSmall } from '@wix/wix-ui-icons-common/lazy';
import type { FC } from 'react';
import React, { useContext, useState } from 'react';

import { RicosContext } from './../../../../../ricos-context/index.js';
import type { Gradient } from './../../../../../ricos-types/color-palette-types.js';
import { schemaGradientToCss } from './../../../../../_shared/schema-gradient-to-css.js';

import { DELETE_GRADIENT_BUTTON, GRADIENT_SWATCH } from '../../data-hooks.js';
import { areGradientsEqual } from './gradient-picker-utils.js';
import classes from './gradient-picker-scss.js';

type CustomGradientsProps = {
  gradients: Gradient[];
  selectedGradient: Gradient;
  onGradientSelected: (gradient: Gradient) => void;
  onGradientDeleted?: (gradient: Gradient) => void;
};

type CustomGradientSwatchProps = {
  gradient: Gradient;
  index: number;
  isSelected: boolean;
  onGradientSelected: (gradient: Gradient) => void;
  onGradientDeleted?: (gradient: Gradient) => void;
};

const CustomGradientSwatch: FC<CustomGradientSwatchProps> = ({
  gradient,
  index,
  isSelected,
  onGradientSelected,
  onGradientDeleted,
}) => {
  const { t, theme } = useContext(RicosContext);
  const [isHovered, setIsHovered] = useState(false);
  const gradientCss = schemaGradientToCss(gradient, theme.colorPalette);

  return (
    <div
      className={classes.customGradientSwatch}
      onMouseEnter={() => setIsHovered(true)}
      onMouseLeave={() => setIsHovered(false)}
    >
      <FillPreview
        id={`${index}`}
        dataHook={GRADIENT_SWATCH}
        selected={isSelected}
        onClick={() => onGradientSelected(gradient)}
        fill={gradientCss}
      />

      {isHovered && onGradientDeleted && (
        <CloseButton
          className={classes.deleteButton}
          dataHook={DELETE_GRADIENT_BUTTON}
          aria-label={t('DeleteButton_Tooltip')}
          skin="standardFilled"
          size="small"
          onMouseDown={event => {
            event.stopPropagation();
          }}
          onClick={event => {
            event.preventDefault();
            event.stopPropagation();
            onGradientDeleted(gradient);
          }}
        >
          <DismissSmall />
        </CloseButton>
      )}
    </div>
  );
};

export const CustomGradients: FC<CustomGradientsProps> = ({
  gradients,
  selectedGradient,
  onGradientSelected,
  onGradientDeleted,
}) => {
  return (
    <div className={classes.customGradientsGrid}>
      {gradients.map((gradient, index) => {
        const isSelected = areGradientsEqual(gradient, selectedGradient);
        return (
          <CustomGradientSwatch
            key={index}
            index={index}
            gradient={gradient}
            isSelected={isSelected}
            onGradientSelected={onGradientSelected}
            onGradientDeleted={onGradientDeleted}
          />
        );
      })}
    </div>
  );
};
