import classNames from 'classnames';
import React, { useContext } from 'react';

import { ResizerHOC } from './../../ricos-common-plugins/resizable/react-resizer.js';
import { RicosContext } from './../../ricos-context/ricos-context.js';
import type { ButtonData } from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import type { PluginProps } from './../../ricos-types/index.js';
import { DraggableHOC } from './../../_shared/draggable-hoc.js';
import { isNodeSelected } from './../../_shared/is-node-selected.js';
import {
  getNodeWidth,
  getPluginContainerClassNames,
  getPluginFocusClassNames,
  getPluginPlacementClassNames,
} from './../../_shared/node-styles.js';
import { OverlayHoc } from './../../_shared/overlay-hoc/overlay-hoc.js';

import { ButtonViewer } from '../viewer/button-viewer.js';

const createStylesHOC = (extraClassName?: string) => (Component: React.FC<PluginProps>) => {
  return (props: PluginProps) => {
    const { isMobile } = useContext(RicosContext);
    const isTextWrapEnabled = props.extension.config.isTextWrap ?? true;

    const className = classNames(
      getPluginContainerClassNames(isMobile),
      getPluginPlacementClassNames(props.node, isTextWrapEnabled),
      extraClassName
    );

    const width = getNodeWidth(props.node, isMobile);

    const style: React.CSSProperties = {
      width: width ? `min(100%, ${width}px)` : undefined,
    };

    return (
      <div className={className} style={style}>
        <Component {...props} />
      </div>
    );
  };
};

const ButtonResizerHOC = (Component: React.FC<PluginProps>) => {
  const ResizableComponent = ResizerHOC(Component);

  return (props: PluginProps) => {
    return props.extension.config.disableResize ? (
      <Component {...props} />
    ) : (
      <ResizableComponent {...props} />
    );
  };
};

const SelectionHOC = (Component: React.FC<PluginProps>) => {
  return (props: PluginProps) => {
    const isFocused = isNodeSelected(props.editor.state, props.node.attrs.id);
    const className = getPluginFocusClassNames(isFocused);

    return (
      <div className={className}>
        <Component {...props} />
      </div>
    );
  };
};

export const Button: React.FC<PluginProps> =
  // We lift button margin to the plugin container so that resizer and selection are not affected
  createStylesHOC()(
    ButtonResizerHOC(
      // Each HOC adds its own props, so the chain composes through loosely-typed
      // boundaries (previously erased by flowRight).
      DraggableHOC(
        SelectionHOC(
          OverlayHoc(({ componentData, settings, node }: PluginProps) => {
            return (
              <ButtonViewer
                nodeId={node.attrs.id}
                buttonData={componentData as ButtonData}
                settings={settings}
              />
            );
          }) as unknown as React.FC<PluginProps>
        ) as unknown as React.FC<PluginProps>
      ) as unknown as React.FC<PluginProps>
    ) as unknown as React.FC<PluginProps>
  );
