import { Box, FieldSet, FillPreview, Input } from '@wix/design-system';
import React, { useContext, useState } from 'react';

import { ZIndexContext } from './../../ricos-context/index.js';
import type { LogBiFn } from './../../_shared/bi-context-provider/bi-context-provider.js';
import { resolveColorToDisplayHex } from './../../_shared/resolve-color-to-display-hex.js';
import { isThemeColorToken } from './../../_shared/theme-color-token.js';
import {
  combineHexWithOpacity,
  getHexColorFromAlpha,
  getOpacityFromHex,
} from './../../wix-rich-content-common/index.js';
import { SWATCH_TOGGLE } from './../color-picker/button-color-swatches/data-hooks.js';
import { InputWithSlider } from './../input-with-slider/input-with-slider.js';
import { usePanelContainerElement } from './../ui-components-provider.js';

export type FillValue =
  | {
      type: 'color';
      color: string | undefined;
      onChange?: (color: string) => void;
      onChangeCommit?: (color: string) => void;
      allowTransparent?: boolean;
    }
  | {
      type: 'gradient';
      gradient: string;
    }
  | {
      type: 'multi-color';
      colors: string[];
    };

type ColorWithOpacityInputProps = {
  fill: FillValue;
  label: React.ReactNode;
  inputDataHook: string;
  onColorPress: () => void;
  colorPickerRef: React.Ref<HTMLDivElement>;
  zIndex: string | number;
  fillPreviewDataHook?: string;
  logBi?: LogBiFn;
};

export const ColorWithOpacityInput: React.FC<ColorWithOpacityInputProps> = ({
  fill,
  label,
  inputDataHook,
  onColorPress,
  colorPickerRef,
  zIndex,
  fillPreviewDataHook,
  logBi,
}) => {
  const zIndexService = useContext(ZIndexContext);
  const panelContainerEl = usePanelContainerElement();
  const [containerElement, setContainerElement] = useState<HTMLDivElement | null>(null);
  const colorResolverElement = panelContainerEl ?? containerElement;

  const isGradient = fill.type === 'gradient';
  const isMultiColor = fill.type === 'multi-color';
  const hasNoOpacity = isGradient || isMultiColor;
  const color = fill.type === 'color' ? fill.color : undefined;
  const onChange = fill.type === 'color' ? fill.onChange : undefined;
  const onChangeCommit = fill.type === 'color' ? fill.onChangeCommit : undefined;

  const hexColor = React.useMemo(
    () => resolveColorToDisplayHex(color, colorResolverElement, { preserveAlpha: true }),
    [color, colorResolverElement]
  );
  const baseColor = React.useMemo(() => {
    if (isThemeColorToken(color)) {
      return getHexColorFromAlpha(color);
    }

    return hexColor?.slice(0, 7);
  }, [color, hexColor]);
  const displayColor = React.useMemo(
    () => resolveColorToDisplayHex(color, colorResolverElement),
    [color, colorResolverElement]
  );
  const isTransparentColor = getOpacityFromHex(hexColor) === 0;
  const [opacity, setOpacity] = useState(() => getOpacityFromHex(hexColor));

  React.useEffect(() => {
    const newOpacity = getOpacityFromHex(hexColor);
    if (newOpacity !== opacity) {
      setOpacity(newOpacity);
    }
  }, [hexColor]);

  const handleOpacityChange = React.useCallback(
    (value: number) => {
      logBi?.({ dataHook: inputDataHook, value });
      const boundedValue = Math.min(100, Math.max(0, Math.round(value)));
      if (boundedValue === opacity) {
        return;
      }

      setOpacity(boundedValue);

      const newColor = combineHexWithOpacity(baseColor, boundedValue);
      if (hexColor !== newColor && newColor && onChange) {
        onChange(newColor);
      }
    },
    [opacity, baseColor, hexColor, onChange]
  );

  const handleOpacityChangeCommit = React.useCallback(
    (finalValue: number) => {
      if (!onChangeCommit) {
        return;
      }
      const boundedValue = Math.min(100, Math.max(0, Math.round(finalValue)));
      const newColor = combineHexWithOpacity(baseColor, boundedValue);
      if (newColor) {
        onChangeCommit(newColor);
      }
    },
    [baseColor, onChangeCommit]
  );

  return (
    <div ref={setContainerElement}>
      <FieldSet
        legend={label}
        legendPlacement="left"
        ellipsis
        columns={hasNoOpacity ? 'auto 30px' : 'auto 72px 30px'}
        gap="small"
        alignment="center"
        infoTooltipProps={{
          appendTo: el => Boolean(el.getAttribute('data-hook')?.includes('ricos-portal')),
          zIndex: zIndexService.getZIndex('TOOLTIP'),
        }}
        dataHook={inputDataHook}
      >
        <div />
        {!hasNoOpacity && (
          <InputWithSlider
            gradientColor={displayColor}
            value={opacity}
            onChange={handleOpacityChange}
            onChangeCommit={onChangeCommit ? handleOpacityChangeCommit : undefined}
            zIndex={zIndex}
            suffix={<Input.Affix>%</Input.Affix>}
            min={0}
            max={100}
          />
        )}
        <Box height={30} width={30}>
          <FillPreview
            fill={
              isGradient
                ? fill.gradient
                : isMultiColor
                  ? fill.colors
                  : isTransparentColor
                    ? undefined
                    : hexColor
            }
            onClick={onColorPress}
            ref={colorPickerRef}
            dataHook={fillPreviewDataHook || SWATCH_TOGGLE}
          />
        </Box>
      </FieldSet>
    </div>
  );
};
