import React from 'react';

type DraggableProps = {
  disabled?: boolean;
};

export const DraggableHOC = <P extends object>(
  Component: React.ComponentType<P>
): React.ComponentType<P & DraggableProps> => {
  const Draggable = (props: P & DraggableProps) => {
    const { disabled, ...restProps } = props;

    return (
      <div {...(disabled ? undefined : { 'data-drag-handle': true, draggable: true })}>
        <Component {...(restProps as P)} />
      </div>
    );
  };
  Draggable.displayName = 'Draggable';

  return Draggable;
};
